-- Compact seed (generated). Spice-level groups intentionally omitted.
do $seed$
declare r uuid; c record; m record; g uuid; i int := 0; x jsonb; cid uuid; mid uuid; n int;
begin
insert into restaurants (slug,name,tagline,address,phone,hours,gst_rate_bp) values ('chackos','Chackos Dining','Kerala & Malabar-Arabian cuisine, casually served','Bhutanese Colony, next to Jazzy Properties (near LPU)','98145 88805','12 PM - 11 PM',500) returning id into r;
for n in 1..14 loop insert into dining_tables (restaurant_id,label) values (r,'T-'||lpad(n::text,2,'0')); end loop;
i := 0;
for x in select jsonb_array_elements('[["mandi","Kuzhi Mandi"],["mandi-combos","Grill Mandi / Biryani"],["shawarma","Shawarma"],["grills","Alfaham & Shawaya"],["curry-breads","Curry & Breads"],["biryani-rice","Biryani & Rice"],["sides-dips","Sides & Dips"],["drinks","Water & Cold Drinks"]]'::jsonb) loop
  insert into categories (restaurant_id,slug,name,sort_order) values (r,x->>0,x->>1,i); i := i+1;
end loop;
i := 0;
for x in select jsonb_array_elements('[["mandi","Kuzhi Mandi (with Mandi Rice)","Authentic Yemeni pit-cooked chicken on smoky fragrant long-grain mandi rice. Served with garlic mayo (toum), spicy tomato chutney (sahawiq) and crisp pickled salad.",22000,null,"8-10 min",["Signature Mandi","Pit-Cooked","Must Try"],true,0,0,1],["mandi","Kuzhi Chicken Only (No Rice)","Tender pit-cooked chicken only (1/4 piece) marinated in traditional Yemeni spices and charred gently in subterranean pit heat. Served with garlic mayo and tomato chutney.",18000,"https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&w=800&q=80","6-8 min",["Keto-Friendly","Protein-Rich"],true,0,0,1],["mandi-combos","Alfaham Mandi / Biryani Combo","Pick your rice: Smoky Mandi Rice or Dum Biryani Rice. Topped with charcoal-grilled Alfaham chicken (1/4 pc) with house spice blend, mayo, chutney & salad.",24000,"https://images.unsplash.com/photo-1633945274405-b6c8069047b0?auto=format&fit=crop&w=800&q=80","10-12 min",["Chef Special","Grill on Rice"],true,1,0,1],["mandi-combos","Shawaya Mandi / Biryani Combo","Pick your rice: Smoky Mandi or Dum Biryani Rice. Topped with golden spit-roasted Shawaya chicken with crisp golden skin, garlic mayo, chutney & salad.",24000,"https://images.unsplash.com/photo-1626082927389-6cd097cdc6ec?auto=format&fit=crop&w=800&q=80","10 min",["Rotisserie","Popular"],true,1,0,1],["mandi-combos","Peri Peri Mandi / Biryani Combo","Tangy and fiery Peri Peri glazed grilled chicken served over your choice of Smoky Mandi Rice or Dum Biryani Rice. With mayo, chutney and salad.",25000,"https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80","12 min",["Fiery Heat","Spicy Lovers"],true,1,0,1],["mandi-combos","Butter Pepper Mandi / Biryani Combo","Rich creamy butter and cracked black pepper coated grilled chicken over Smoky Mandi or Dum Biryani Rice. Served with mayo, chutney and salad.",25000,"https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&w=800&q=80","12 min",["Malabar Pepper","Rich Butter"],true,1,0,1],["mandi-combos","Shawaya Masala Mandi / Biryani Combo","Spit-roasted rotisserie chicken rubbed with aromatic Indian masala over your choice of Smoky Mandi or Dum Biryani Rice. Includes Shawaya masala dip.",25000,"https://images.unsplash.com/photo-1610057099443-fde8c4d50f91?auto=format&fit=crop&w=800&q=80","10 min",["Desi Spiced","Signature"],true,1,0,1],["mandi-combos","Honey Chilli Mandi / Biryani Combo","Sweet golden wild honey and roasted red chilli heat glazed grilled chicken on fragrant Mandi or Dum Biryani Rice with garlic mayo and salad.",26000,"https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80","12 min",["Sweet & Spicy","Chef Favorite"],true,1,0,1],["mandi-combos","Creamy Mandi / Biryani Combo","Creamy garlic-herb marinated chicken grilled to succulent perfection, served over hot Mandi or Dum Biryani Rice. Rich, aromatic and mild.",27000,"https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&w=800&q=80","12 min",["Melt-In-Mouth","Creamy"],true,1,0,1],["shawarma","Chicken Shawarma Roll","Spit-roasted chicken, house garlic mayo (toum) and crunchy pickles rolled in soft freshly-made bread. Small spicy pickled salad on the side, free.",13000,"https://images.unsplash.com/photo-1561651823-34feb02250e4?auto=format&fit=crop&w=800&q=80","5 min",["BESTSELLER","Street Classic"],true,0,0,1],["shawarma","Full Meat Shawarma Roll","Double portion of slow-roasted chicken, rich garlic mayo, zero veggies. Pure roasted meat wrapped in warm soft bread for true meat lovers.",18000,"https://images.unsplash.com/photo-1529042410759-befb1204b468?auto=format&fit=crop&w=800&q=80","5 min",["Double Meat","Zero Veggies","Carnivore Pick"],true,0,0,1],["shawarma","Shawarma Plate","Spit-roasted shawarma chicken served open on a platter with paper-thin Rumali Roti, creamy garlic mayo and spicy house-pickled salad.",16000,"https://images.unsplash.com/photo-1529006557810-274b9b2fc783?auto=format&fit=crop&w=800&q=80","6 min",["Open Platter","Includes Rumali"],true,0,0,1],["grills","Alfaham Classic (1 Pc)","Charcoal-grilled quarter chicken marinated in house Arabian-Kerala Alfaham spice blend. Includes 1 garlic mayo, 1 chutney, and side: rumali free or porotta +₹5.",18000,"https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&w=800&q=80","12-14 min",["Charcoal Grilled","1 Pc = ¼ Chicken"],true,0,1,1],["grills","Alfaham Peri Peri (1 Pc)","Tangy, fiery peri peri glaze over charcoal-grilled quarter chicken. Includes 1 garlic mayo, 1 chutney, and side: rumali free or porotta +₹5.",19000,"https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80","12-14 min",["Spicy Tangy","Fiery Glaze"],true,0,1,1],["grills","Alfaham Butter Pepper (1 Pc)","Charcoal chicken smothered in melted butter and coarse cracked Malabar black pepper. Includes 1 garlic mayo, 1 chutney, and rumali or porotta.",19000,"https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&w=800&q=80","12-14 min",["Black Pepper","Butter Glazed"],true,0,1,1],["grills","Alfaham Honey Chilli (1 Pc)","Sweet natural honey and hot crushed red chilli seeds glazed over sizzling charcoal chicken. Includes garlic mayo, chutney, rumali or porotta.",20000,"https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=800&q=80","12-14 min",["Sweet Heat","Popular"],true,0,1,1],["grills","Alfaham Creamy (1 Pc)","Creamy garlic-herb marinade on charcoal quarter chicken. Velvet smooth texture with mild warmth. Includes garlic mayo, chutney, rumali or porotta.",21000,"https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&w=800&q=80","12-14 min",["Rich Creamy","Melt In Mouth"],true,0,1,1],["grills","Shawaya Classic (1 Pc)","Spit-roasted rotisserie quarter chicken with crisp golden skin and juicy meat. Includes 1 garlic mayo, 1 Shawaya masala dip, and rumali or porotta.",18000,"https://images.unsplash.com/photo-1626082927389-6cd097cdc6ec?auto=format&fit=crop&w=800&q=80","8 min",["Rotisserie Crisp","Juicy Skin"],true,0,1,1],["grills","Shawaya Masala (1 Pc)","Rotisserie quarter chicken rubbed with deep Indian roast masala spices. Includes 1 garlic mayo, 1 Shawaya masala dip, and rumali or porotta.",19000,"https://images.unsplash.com/photo-1610057099443-fde8c4d50f91?auto=format&fit=crop&w=800&q=80","8 min",["Masala Rub","Desi Roast"],true,0,1,1],["curry-breads","Chackos Chicken Curry","Traditional Kerala-style chicken curry slow-simmered in rich onion-tomato gravy with fresh curry leaves, coconut oil aroma and aromatic Malabar spices.",13000,"https://images.unsplash.com/photo-1603894584373-5ac82b2ae398?auto=format&fit=crop&w=800&q=80","6 min",["Kerala Homestyle","Curry Leaf Aroma"],true,0,0,1],["curry-breads","Kerala Porotta","Soft, flaky, spiral multi-layered traditional Malabar flatbread beaten hot off the tawa. Contains egg. The quintessential pair with Chackos Chicken Curry or Alfaham.",2000,"https://images.unsplash.com/photo-1626777552726-4a6b54c97e46?auto=format&fit=crop&w=800&q=80","2 min",["Flaky Malabar","Must Order"],true,0,0,1],["curry-breads","Rumali Roti","Paper-thin handkerchief bread baked on an inverted domed tawa. Soft, delicate, and wraps effortlessly around juicy grilled meats.",1500,"https://images.unsplash.com/photo-1506084868230-bb9d95c24759?auto=format&fit=crop&w=800&q=80","2 min",["Paper Thin","Light"],true,0,0,1],["biryani-rice","Chicken Dum Biryani","South Indian dum, layered spiced rice with tender bone-in chicken marinated in yogurt, mint, green chillies and golden fried onions. Medium spice.",14000,"https://images.unsplash.com/photo-1563379091339-03b21ab4a4f8?auto=format&fit=crop&w=800&q=80","5 min",["South Indian Dum","Value Feast"],true,0,0,0],["biryani-rice","Mandi Rice (1 Portion)","A single portion of smoky, golden aromatic Mandi rice prepared with cardamom, dried lime (loomi), cloves, and subterranean charcoal essence.",6000,"https://images.unsplash.com/photo-1596797038530-2c107229654b?auto=format&fit=crop&w=800&q=80","2 min",["Smoky Fragrant","Extra Portion"],true,0,0,0],["biryani-rice","Biryani Rice (1 Portion)","A single portion of fragrant South Indian dum biryani rice cooked with ghee, fried onions, and whole spices.",6000,"https://images.unsplash.com/photo-1596797038530-2c107229654b?auto=format&fit=crop&w=800&q=80","2 min",["Spiced Dum Rice","Extra Portion"],true,0,0,0],["sides-dips","Fresh Salad Plate","Crisp garden fresh cucumber, carrot and green chilli slices.",4000,"https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80","2 min",["Fresh Veg"],true,0,0,0],["sides-dips","Pickled Salad (Spicy)","House-made spicy cabbage, carrot, and beetroot pickle brined with vinegar and green chillies.",4000,"https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80","2 min",["House Brined","Tangy Spicy"],true,0,0,0],["sides-dips","Onion Plate with Lemon","Thinly sliced crisp red onion rings served with juicy fresh lemon wedges.",3000,"https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=800&q=80","2 min",["Crisp Onion"],true,0,0,0],["sides-dips","Garlic Mayo (Toum Dip)","Extra cup of Chackos signature fluffy white garlic toum mayonnaise. Creamy, punchy and velvety.",2000,"https://images.unsplash.com/photo-1472476443507-c7a5948772fc?auto=format&fit=crop&w=800&q=80","1 min",["Signature Toum","House Favorite"],true,0,0,0],["sides-dips","Tomato Chutney (Sahawiq/Dakkoos)","Spicy Arabian-Kerala tomato dip blended with green chillies, garlic and fresh cilantro.",2000,"https://images.unsplash.com/photo-1472476443507-c7a5948772fc?auto=format&fit=crop&w=800&q=80","1 min",["Spicy Dakkoos"],true,0,0,0],["sides-dips","Mint Chutney","Refreshing green chutney prepared with garden fresh mint, coriander, roasted cumin and green chillies.",2000,"https://images.unsplash.com/photo-1472476443507-c7a5948772fc?auto=format&fit=crop&w=800&q=80","1 min",["Cooling Mint"],true,0,0,0],["sides-dips","Shawaya Masala Dip","Spiced aromatic masala gravy dip specially crafted for dipping rotisserie Shawaya chicken.",2000,"https://images.unsplash.com/photo-1472476443507-c7a5948772fc?auto=format&fit=crop&w=800&q=80","1 min",["Shawaya Special"],true,0,0,0],["drinks","Packaged Water & Chilled Cans","A changing selection of bottled mineral water and chilled cold drinks (Thums Up, Coca Cola, Sprite). Always at MRP. Ask staff what is chilled today.",2000,"https://images.unsplash.com/photo-1622483767028-3f66f32aef97?auto=format&fit=crop&w=800&q=80","1 min",["Chilled Cans","At MRP"],true,0,0,0]]'::jsonb) loop
  select id into cid from categories where restaurant_id=r and slug=x->>0;
  insert into menu_items (restaurant_id,category_id,name,description,price_paise,image_url,prep_time,tags,is_available,sort_order)
  values (r,cid,x->>1,x->>2,(x->>3)::int,x->>4,x->>5,array(select jsonb_array_elements_text(x->6)),(x->>7)::boolean,i) returning id into mid;
  i := i+1;
  n := 0;
  if (x->>8)='1' then
    insert into modifier_groups (menu_item_id,name,min_select,max_select,sort_order) values (mid,'Choose your rice',1,1,n) returning id into g; n:=n+1;
    insert into modifier_options (group_id,name,price_delta_paise,is_default,sort_order) values (g,'Smoky Mandi Rice',0,true,0),(g,'Dum Biryani Rice',0,false,1);
  end if;
  if (x->>9)='1' then
    insert into modifier_groups (menu_item_id,name,min_select,max_select,sort_order) values (mid,'Choose your bread',1,1,n) returning id into g; n:=n+1;
    insert into modifier_options (group_id,name,price_delta_paise,is_default,sort_order) values (g,'Rumali Roti (free)',0,true,0),(g,'Kerala Porotta',500,false,1);
  end if;
  if (x->>10)='1' then
    insert into modifier_groups (menu_item_id,name,min_select,max_select,sort_order) values (mid,'Extra dips',0,4,n) returning id into g;
    insert into modifier_options (group_id,name,price_delta_paise,is_default,sort_order) values (g,'Garlic Mayo (Toum)',2000,false,0),(g,'Tomato Chutney (Sahawiq)',2000,false,1),(g,'Mint Chutney',2000,false,2),(g,'Shawaya Masala Dip',2000,false,3);
  end if;
end loop;
end $seed$;
